"""GĐ9.Q pages: Custom Apps (replaces the tutorial-only page), Server settings (headers / cache / checkpointer / authentication / SSO / docs),
LLM Gateway policies & routing. Written on the same building blocks as ui_ls3 (page(), hdr(), pane(), api())."""
from ui_ls3 import P

APPS = P("apps", "Custom Apps", """<div class="ph" id="h"></div><div class="bodyx" id="b"></div>""", r"""
let APPS=[],TPL=[];
const lines=t=>t.split('\n').map(x=>x.trim()).filter(Boolean);
async function list(){[APPS,TPL]=await Promise.all([api('api/apps'),api('api/apps/templates')]);
 $('h').innerHTML=hdr('box','Custom Apps','<span class="muted">Small web apps next to your agents. They run in a sandbox with no network; every API call they make uses your own permissions.</span>',`<button id="na">${ICN('plus')}App</button>`);
 $('b').innerHTML=(APPS.length?`<div class="card" style="padding:0"><table><thead><tr><th>Name</th><th>Description</th><th>Version</th><th>Updated</th><th>Created by</th><th></th></tr></thead><tbody>${APPS.map(a=>`<tr><td><a href="apps/view/${a.id}"><b>${esc(a.name)}</b></a> <span class="mono muted" style="font-size:11px">${a.id}</span></td><td class="muted">${esc(a.description||'')}</td><td><span class="chip">v${a.version}</span></td><td>${esc(dt(a.updated))}</td><td>${esc(a.created_by||'')}</td><td style="text-align:right"><a class="btn g sm" href="apps/view/${a.id}">${ICN('external-link')}Open</a> <a class="btn g sm" href="apps?edit=${a.id}">${ICN('square-pen')}Edit</a> <button class="gh" data-del="${a.id}">${ICN('trash-2')}</button></td></tr>`).join('')}</tbody></table></div>`:
  `<div class="card">${emptyState('box','No custom apps yet','Build a small web app on top of your agents: pick a template and edit it here, or push a folder from your computer with the aos CLI.',`<button id="na2">${ICN('plus')}New app</button>`)}</div>`)+
  `<div class="card"><div class="h4">From your computer</div><pre>pip install httpx        # the CLI needs only httpx
export AOS_URL=${esc(location.origin)} AOS_API_KEY=aos_…
python aos_cli.py apps init my-app --template agent-chat
python aos_cli.py apps push my-app      # creates, then updates the same app</pre><div class="muted" style="font-size:12.5px">Inside an app, <code>aos.json(method, path, body)</code> calls Agent OS as the person who opened the app. Keys, members, secrets, SSO and service keys are blocked for apps.</div></div>`;
 const mk=()=>pane('New custom app',`<label>Name</label><input id="an" style="width:100%" placeholder="My app"><label>Description</label><input id="ad" style="width:100%"><label>Start from</label><div class="tpl" style="grid-template-columns:1fr">${TPL.map((t,i)=>`<label class="ccard" style="cursor:pointer"><input type="radio" name="atp" value="${t.key}" ${i===0?'checked':''}> <b>${esc(t.title)}</b><div class="muted" style="font-size:12.5px">${esc(t.description)}</div></label>`).join('')}</div><div class="row" style="margin-top:12px"><span class="sp"></span><button class="g" onclick="closePane()">Cancel</button><button id="ago">Create</button></div>`,p=>{p.querySelector('#ago').onclick=async()=>{const n=p.querySelector('#an').value.trim();if(!n)return flash('Enter a name',1);try{const r=await api('api/apps','POST',{name:n,description:p.querySelector('#ad').value,template:p.querySelector('[name=atp]:checked').value});location.href='apps?edit='+r.id}catch(e){flash(e.message,1)}}});
 $('na').onclick=mk;const n2=document.getElementById('na2');if(n2)n2.onclick=mk;
 document.querySelectorAll('[data-del]').forEach(x=>x.onclick=async()=>{if(!confirm('Delete this app and its versions?'))return;await api('api/apps/'+x.dataset.del,'DELETE');flash('Deleted');list()})}
async function edit(id){const a=await api('api/apps/'+id);let files={...a.files},cur=a.entry,dirty=false;
 $('h').innerHTML=`<div class="muted" style="font-size:12px;margin-bottom:6px"><a href="apps">Custom Apps</a> / ${esc(a.name)}</div>`+hdr('box',esc(a.name),`<span class="chip" id="av">v${a.version}</span>`,`<a class="btn g" href="apps/view/${id}" target="_blank" rel="noopener">${ICN('external-link')}Open</a><button class="g" id="ver">${ICN('history')}Versions</button><button id="sv">${ICN('save')}Save</button>`);
 $('b').innerHTML=`<div class="ide"><div class="ex" id="ex"></div><div><textarea id="ed" spellcheck="false"></textarea></div><div class="pv"><div class="muted" style="font-size:12px;margin-bottom:6px">Preview (sandboxed)</div><iframe id="pvf" sandbox="allow-scripts" style="width:100%;height:58vh;border:1px solid var(--bd2);border-radius:var(--r-md)" src="apps/frame/${id}"></iframe></div></div>`;
 const ed=$('ed');
 const draw=()=>{$('ex').innerHTML=Object.keys(files).sort().map(p=>`<a data-f="${esc(p)}" class="${p===cur?'on':''}">${ICN('file-text')}<span style="flex:1">${esc(p)}</span>${p===a.entry?'<span class="muted" style="font-size:10px">entry</span>':`<button class="gh" data-rm="${esc(p)}" style="padding:0 4px">${ICN('x')}</button>`}</a>`).join('')+`<a id="addf" class="muted">${ICN('plus')}File</a>`;
  ed.value=files[cur]||'';
  $('ex').querySelectorAll('[data-f]').forEach(x=>x.onclick=e=>{if(e.target.closest('[data-rm]'))return;cur=x.dataset.f;draw()});
  $('ex').querySelectorAll('[data-rm]').forEach(x=>x.onclick=()=>{if(confirm('Remove '+x.dataset.rm+'?')){delete files[x.dataset.rm];if(cur===x.dataset.rm)cur=a.entry;dirty=true;draw()}});
  $('addf').onclick=()=>{const n=prompt('File name (.html .css .js .json .svg .txt .md)','extra.js');if(n&&!files[n]){files[n]='';cur=n;dirty=true;draw()}}};
 ed.oninput=()=>{files[cur]=ed.value;dirty=true};draw();
 $('sv').onclick=async()=>{try{const r=await api('api/apps/'+id,'PUT',{files});dirty=false;$('av').textContent='v'+r.version;$('pvf').src='apps/frame/'+id;flash('Saved as v'+r.version)}catch(e){flash(e.message,1)}};
 $('ver').onclick=async()=>{const V=await api('api/apps/'+id+'/versions');pane('Versions',`<table><thead><tr><th>Version</th><th>By</th><th>When</th><th>Files</th><th></th></tr></thead><tbody>${V.map(v=>`<tr><td>v${v.version}</td><td>${esc(v.created_by||'')}</td><td>${esc(dt(v.created))}</td><td>${v.files}</td><td><button class="g sm" data-rs="${v.version}">Restore</button></td></tr>`).join('')}</tbody></table>`,p=>p.querySelectorAll('[data-rs]').forEach(x=>x.onclick=async()=>{if(!confirm('Restore v'+x.dataset.rs+' as a new version?'))return;await api('api/apps/'+id+'/restore','POST',{version:+x.dataset.rs});flash('Restored');edit(id);closePane()}))};
 // the preview frame talks to this page exactly like the real host page does (same bridge, same server-side block list)
 addEventListener('message',async e=>{if(e.source!==$('pvf').contentWindow)return;const d=e.data;if(!d||d.aos!==1||typeof d.id!=='number')return;const reply=o=>$('pvf').contentWindow.postMessage({aosReply:1,id:d.id,...o},'*');
  try{const r=await fetch('api/app-call/'+id,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:String(d.method||'GET'),path:String(d.path||''),body:d.body===undefined?null:d.body})});const j=await r.json().catch(()=>null);reply(r.ok?{status:j.status,json:j.json,text:j.text}:{status:r.status,json:j})}catch(x){reply({status:0,json:{detail:String(x)}})}});
 window.onbeforeunload=()=>dirty?'Unsaved changes':undefined}
(QS.get('edit')?edit(QS.get('edit')):list()).catch(e=>flash(e.message,1));
""")

SERVER_CFG = P("srvcfg", "Server settings", """<div class="ph" id="h"></div><div class="bodyx" id="b"></div>""", r"""
let TAB=QS.get('tab')||'headers';
const lines=t=>t.split('\n').map(x=>x.trim()).filter(Boolean);
const tabs=[['headers','Headers & logs'],['cache','Cache'],['checkpointer','Checkpointer'],['auth','Authentication'],['sso','Single sign-on'],['docs','Docs']];
async function draw(){$('h').innerHTML=hdr('settings','Server settings','<span class="muted">Agent Server behaviour: what the code in <code>aos.json</code> and these screens control.</span>')+tabsHtml(tabs,TAB);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{TAB=b.dataset.tab;history.replaceState(null,'','?tab='+TAB);draw()});
 const b=$('b');b.innerHTML=`<div class="muted">${ICN('loader')} Loading…</div>`;
 try{await({headers:tHeaders,cache:tCache,checkpointer:tCp,auth:tAuth,sso:tSso,docs:tDocs}[TAB])(b)}catch(e){b.innerHTML=`<div class="card"><div class="muted">${esc(e.message)}</div></div>`}}
async function tHeaders(b){const c=await api('api/server-config'),h=c.http;
 b.innerHTML=`<div class="grid2" style="align-items:start"><div class="card"><div class="h4">Headers for runtime configuration</div><div class="muted" style="font-size:12.5px;margin:2px 0 8px">Request headers copied into the run's <code>config["configurable"]</code> (like LangGraph's <code>http.configurable_headers</code>). One pattern per line, <code>*</code> matches any characters.</div>
  <label>Include</label><textarea id="ci" rows="4" class="mono">${esc(h.configurable_headers.includes.join('\n'))}</textarea><label>Exclude <small class="muted">(wins over include)</small></label><textarea id="ce" rows="3" class="mono">${esc(h.configurable_headers.excludes.join('\n'))}</textarea></div>
  <div class="card"><div class="h4">Headers in server logs</div><div class="muted" style="font-size:12.5px;margin:2px 0 8px">By default no header is logged. Allowed headers are written with every API request line and kept 7 days for search; values are shortened and cleaned.</div>
  <label>Include</label><textarea id="li" rows="4" class="mono">${esc(h.logging_headers.includes.join('\n'))}</textarea><label>Exclude</label><textarea id="le" rows="3" class="mono">${esc(h.logging_headers.excludes.join('\n'))}</textarea></div></div>
  <div class="row"><button id="hs">Save</button><button class="g" id="hr">Reset to aos.json</button><span class="muted" style="font-size:12.5px">Never allowed, whatever the lists say: ${c.hard_denied.map(x=>'<code>'+esc(x)+'</code>').join(' ')}</span></div>
  ${c.source.file_error?`<div class="card" style="border-color:var(--er)"><b>aos.json is invalid and ignored</b><pre>${esc(c.source.file_error)}</pre></div>`:''}
  <div class="card"><div class="h4">Try it</div><textarea id="tt" rows="4" class="mono" placeholder="x-organization-id: org-7&#10;authorization: Bearer abc&#10;x-request-id: r-1"></textarea><div class="row" style="margin-top:6px"><button class="g" id="hdrtest">Test these headers</button></div><div id="tr"></div></div>
  <div class="card" style="padding:0"><div class="row" style="padding:12px 14px"><div class="h4">Request log</div><span class="sp"></span><input id="lh" placeholder="header (e.g. x-request-id)" style="width:200px"><input id="lv" placeholder="value" style="width:160px"><button class="g" id="lf">Filter</button></div><div id="lt"></div></div>`;
 const hdrs=()=>({configurable_headers:{includes:lines($('ci').value),excludes:lines($('ce').value)},logging_headers:{includes:lines($('li').value),excludes:lines($('le').value)}});
 $('hs').onclick=async()=>{try{await api('api/server-config/http','PUT',hdrs());flash('Saved');tHeaders(b)}catch(e){flash(e.message,1)}};
 $('hr').onclick=async()=>{await api('api/server-config/http','DELETE');flash('Reset');tHeaders(b)};
 $('hdrtest').onclick=async()=>{const hs={};lines($('tt').value).forEach(l=>{const i=l.indexOf(':');if(i>0)hs[l.slice(0,i).trim()]=l.slice(i+1).trim()});try{const r=await api('api/server-config/headers/test','POST',{headers:hs});
  $('tr').innerHTML=`<div class="cards" style="margin-top:10px"><div class="ccard"><div class="t">Reach the run config</div><pre>${esc(JSON.stringify(r.configurable,null,1))}</pre></div><div class="ccard"><div class="t">Would be logged</div><pre>${esc(JSON.stringify(r.logged,null,1))}</pre></div></div>${r.dropped.length?`<div class="muted">Dropped as credentials: ${r.dropped.map(esc).join(', ')}</div>`:''}`}catch(e){flash(e.message,1)}};
 const logs=async()=>{const q=new URLSearchParams({limit:50});if($('lh').value)q.set('header',$('lh').value);if($('lv').value)q.set('value',$('lv').value);const L=(await api('api/server-config/logs?'+q)).logs;
  $('lt').innerHTML=`<table><thead><tr><th>When</th><th>Request</th><th>Status</th><th>ms</th><th>Headers</th></tr></thead><tbody>${L.map(r=>`<tr><td>${esc(dt(r.ts))}</td><td class="mono">${esc(r.method)} ${esc(r.path)}</td><td>${r.status}</td><td>${r.ms}</td><td class="mono" style="font-size:12px">${esc(JSON.stringify(r.headers))}</td></tr>`).join('')||`<tr><td colspan="5" class="muted">No request with a logged header yet.</td></tr>`}</tbody></table>`};
 $('lf').onclick=logs;logs()}
async function tCache(b){const [c,L]=await Promise.all([api('api/server-config'),api('api/cache')]);
 b.innerHTML=`<div class="cards"><div class="ccard"><div class="t">Entries in this workspace</div><div class="v">${c.cache.entries}</div></div><div class="ccard"><div class="t">Longest lifetime</div><div class="v">${Math.round(c.cache.max_ttl_s/3600)} h</div></div></div>
 <div class="card"><div class="muted" style="font-size:12.5px">Server-side cache for graphs and tools (like <code>langgraph_sdk.cache</code>): <code>swr(key, loader, fresh_for, max_age)</code>, <code>cache_get / cache_set</code>, and a Postgres <code>PgCache</code> for LangGraph node <code>CachePolicy</code>. Values are JSON up to 256 KB, per workspace, lifetime at most one day.</div></div>
 <div class="card" style="padding:0"><table><thead><tr><th>Key</th><th>Size</th><th>Created</th><th>Expires</th><th></th></tr></thead><tbody>${L.map(r=>`<tr><td class="mono">${esc(r.key)}</td><td>${r.bytes} B</td><td>${esc(dt(r.created))}</td><td>${esc(dt(r.expires))}</td><td><button class="gh" data-k="${esc(r.key)}">${ICN('trash-2')}</button></td></tr>`).join('')||`<tr><td colspan="5" class="muted">Nothing cached.</td></tr>`}</tbody></table></div>`;
 b.querySelectorAll('[data-k]').forEach(x=>x.onclick=async()=>{await api('api/cache/'+encodeURI(x.dataset.k),'DELETE');tCache(b)})}
async function tCp(b){const c=await api('api/server-config'),k=c.checkpointer;
 b.innerHTML=`<div class="card"><div class="h4">Checkpointer</div><div class="row" style="margin:8px 0"><span class="chip ok">${esc(k.kind)}</span><span class="muted">from ${esc(k.source)}</span>${k.path?`<code>${esc(k.path)}</code>`:''}${k.custom?`<code>${esc(k.custom)}</code>`:''}</div>
 <div class="muted" style="font-size:13px;line-height:1.7">Where thread state is stored. <b>postgres</b> is the default (supports per-workspace encryption of checkpoints). Alternatives are chosen in <code>aos.json</code> or the environment, never from this screen (they load code):<pre>"checkpointer": "postgres"
"checkpointer": "sqlite:///var/checkpoints.db"
"checkpointer": "memory"                       // development only
"checkpointer": {"path": "./checkpointer.py:generate_checkpointer"}   // your own async context manager</pre>
 A custom checkpointer is opened once at start and must pass a put / get / list / delete smoke test; restart the service to change it. The same file path can be given with <code>AOS_CHECKPOINTER=custom:/path/cp.py:fn</code>.</div></div>`}
async function tAuth(b){const s=await api('api/server-config/auth'),pol=JSON.stringify(s.policy.rules.length?s.policy:{rules:[{resources:['threads'],actions:['*'],mode:'owner',admin_bypass:true}]},null,1);
 b.innerHTML=`<div class="grid2" style="align-items:start"><div class="card"><div class="h4">Custom authentication module</div>
  <div class="row" style="margin:8px 0">${s.configured?(s.loaded?'<span class="chip ok">Loaded</span>':'<span class="chip er">Failed — API closed</span>'):'<span class="chip">Not configured</span>'}${s.module?`<code>${esc(s.module)}</code>`:''}</div>
  ${s.error?`<pre style="color:var(--er)">${esc(s.error)}</pre>`:''}
  <table><tbody><tr><td class="muted">@auth.authenticate</td><td>${s.authenticate?'yes':'no'}</td></tr><tr><td class="muted">@auth.on handlers</td><td class="mono" style="font-size:12px">${esc(s.handlers.join(', ')||'none')}</td></tr><tr><td class="muted">Applies on</td><td class="mono">${esc(s.paths.join(', '))}</td></tr><tr><td class="muted">Highest role</td><td>${esc(s.max_role)}</td></tr><tr><td class="muted">Workspace of identities</td><td>${s.workspace}</td></tr></tbody></table>
  <div class="muted" style="font-size:12.5px;margin-top:8px">Write <code>auth.py</code> with the official <code>langgraph_sdk.Auth</code> and point <code>"auth": {"path": "./auth.py:auth"}</code> at it in <code>aos.json</code> (see Docs). While a module is active, every Agent Server API route must be covered by the handlers; a broken module closes the API instead of opening it.</div></div>
  <div class="card"><div class="h4">Declarative policy <small class="muted">(no code)</small></div><div class="muted" style="font-size:12.5px;margin:2px 0 6px">First matching rule wins. <b>owner</b> = stamp <code>metadata.owner</code> on writes and filter every read; <b>deny</b>; <b>allow</b>. Optional: <code>roles</code>, <code>workspaces</code>, <code>admin_bypass</code>.</div><textarea id="pj" rows="12" class="mono" style="width:100%">${esc(pol)}</textarea><div class="row" style="margin-top:8px"><button id="ps">Save policy</button><button class="g" id="pc">Remove all rules</button></div></div></div>
  <div class="card"><div class="h4">Dry run</div><div class="row"><input id="di" placeholder="identity" value="alice" style="width:140px"><select id="dr"><option>editor</option><option>viewer</option><option>admin</option></select><select id="dm"><option>POST</option><option>GET</option><option>PATCH</option><option>DELETE</option></select><input id="dp" value="/api/v1/threads" style="width:260px" class="mono"><button class="g" id="dg">Decide</button></div><pre id="dout" style="margin-top:8px"></pre></div>`;
 $('ps').onclick=async()=>{try{await api('api/server-config/auth-policy','PUT',JSON.parse($('pj').value));flash('Policy saved');tAuth(b)}catch(e){flash(e.message,1)}};
 $('pc').onclick=async()=>{await api('api/server-config/auth-policy','PUT',{rules:[]});flash('Policy removed');tAuth(b)};
 $('dg').onclick=async()=>{try{const r=await api('api/server-config/auth/test','POST',{identity:$('di').value,role:$('dr').value,method:$('dm').value,path:$('dp').value,body:{}});$('dout').textContent=JSON.stringify(r,null,1)}catch(e){flash(e.message,1)}}}
async function tSso(b){const [o,x,P]=await Promise.all([api('api/admin/oidc'),api('api/admin/oidc/extra'),api('api/admin/oidc/presets')]);const PR=P.presets;
 b.innerHTML=`<div class="card"><div class="h4">Identity provider</div><div class="muted" style="font-size:12.5px;margin:2px 0 8px">People sign in with OpenID Connect; programs can send the provider's JWT as <code>Authorization: Bearer</code> on the Agent Server API. The client secret stays in the service <code>.env</code> — only its variable name is stored here.</div>
  <div class="row"><label style="margin:0">Preset</label><select id="pre"><option value="">Custom / other</option>${Object.entries(PR).map(([k,v])=>`<option value="${k}" ${x.preset===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select><span id="pp" class="row" style="gap:6px"></span><button class="g" id="pf">Fill the form</button></div><div id="pn" class="muted" style="font-size:12.5px;margin-top:6px"></div></div>
  <div class="grid2" style="align-items:start"><div class="card"><div class="h4">Sign-in</div>
   <label class="row" style="gap:6px"><input type="checkbox" id="oe" ${o.enabled?'checked':''}> Enabled</label>
   <label>Issuer</label><input id="oi" value="${esc(o.issuer||'')}" style="width:100%"><label>Client ID</label><input id="oc" value="${esc(o.client_id||'')}" style="width:100%"><label>Client secret variable <small class="muted">${o.secret_present?'· found in the environment':'· not set'}</small></label><input id="os" value="${esc(o.client_secret_env||'')}" placeholder="AOS_OIDC_SECRET" style="width:100%">
   <label>Scopes</label><input id="osc" value="${esc(o.scopes||'openid email profile')}" style="width:100%"><label>Username claim</label><input id="ou" value="${esc(o.username_claim||'preferred_username')}" style="width:100%">
   <div class="row" style="margin-top:6px"><label style="margin:0">Default role</label><select id="odr"><option ${o.default_role==='viewer'?'selected':''}>viewer</option><option ${o.default_role==='editor'?'selected':''}>editor</option></select><label style="margin:0">Workspace</label><input id="odw" type="number" value="${o.default_workspace||1}" style="width:70px"></div>
   <label class="row" style="gap:6px"><input type="checkbox" id="oa" ${o.auto_create?'checked':''}> Create accounts on first sign-in</label><label>Allowed e-mail domains <small class="muted">(comma separated)</small></label><input id="od" value="${esc((o.allowed_domains||[]).join(', '))}" style="width:100%"><label>Button label</label><input id="ob" value="${esc(o.button_label||'Sign in with SSO')}" style="width:100%"></div>
  <div class="card"><div class="h4">Groups → roles</div><label>Group claim <small class="muted">(e.g. groups, roles, realm_access.roles)</small></label><input id="gc" value="${esc(x.group_claim||'')}" style="width:100%">
   <label>Mapping <small class="muted">group → {role, workspace}</small></label><textarea id="gm" rows="6" class="mono" style="width:100%">${esc(JSON.stringify(x.group_map||{},null,1))}</textarea>
   <label>Allowed groups <small class="muted">(empty = anyone)</small></label><input id="ga" value="${esc((x.allowed_groups||[]).join(', '))}" style="width:100%">
   <label class="row" style="gap:6px"><input type="checkbox" id="gr" ${x.require_group?'checked':''}> Require a mapped group</label><label class="row" style="gap:6px"><input type="checkbox" id="gs" ${x.sync_roles?'checked':''}> Sync: remove memberships the groups no longer grant</label><label class="row" style="gap:6px"><input type="checkbox" id="gad" ${x.allow_admin?'checked':''}> Allow the admin role from groups <small class="muted">(otherwise capped at editor)</small></label>
   <div class="h4" style="margin-top:10px">API access</div><label class="row" style="gap:6px"><input type="checkbox" id="gt" ${x.api_tokens?'checked':''}> Accept the provider's JWT as a Bearer token on /api/v1</label><label>Audience</label><input id="gau" value="${esc(x.api_audience||'')}" placeholder="defaults to the client ID" style="width:100%"></div></div>
  <div class="row"><button id="ssv">Save</button><span class="muted" style="font-size:12.5px">Callback URL for the provider: <code>${esc(location.origin)}/login/oidc/callback</code></span></div>`;
 const pp=()=>{const k=$('pre').value;$('pp').innerHTML=k?PR[k].params.map(p=>`<input data-pp="${p}" placeholder="${p}" style="width:150px">`).join(''):'';$('pn').textContent=k?PR[k].note:''};$('pre').onchange=pp;pp();
 $('pf').onclick=async()=>{const k=$('pre').value;if(!k)return;const params={};b.querySelectorAll('[data-pp]').forEach(i=>params[i.dataset.pp]=i.value);try{const r=await api('api/admin/oidc/presets/'+k+'/render','POST',{params});$('oi').value=r.issuer;$('osc').value=r.scopes;$('ou').value=r.username_claim;if(r.group_claim)$('gc').value=r.group_claim;$('ob').value=r.button_label;$('pn').textContent=r.note}catch(e){flash(e.message,1)}};
 $('ssv').onclick=async()=>{try{const cs=t=>t.split(',').map(s=>s.trim()).filter(Boolean);
  await api('api/admin/oidc','PUT',{enabled:$('oe').checked,issuer:$('oi').value||null,client_id:$('oc').value||null,client_secret_env:$('os').value||null,scopes:$('osc').value,username_claim:$('ou').value,auto_create:$('oa').checked,default_role:$('odr').value,default_workspace:+$('odw').value,allowed_domains:cs($('od').value).length?cs($('od').value):null,button_label:$('ob').value});
  await api('api/admin/oidc/extra','PUT',{preset:$('pre').value||null,group_claim:$('gc').value||null,group_map:JSON.parse($('gm').value||'{}'),allowed_groups:cs($('ga').value).length?cs($('ga').value):null,require_group:$('gr').checked,sync_roles:$('gs').checked,allow_admin:$('gad').checked,api_tokens:$('gt').checked,api_audience:$('gau').value||null});flash('Saved');tSso(b)}catch(e){flash(e.message,1)}}}
async function tDocs(b){const L=(await api('api/server-docs')).pages;let cur=QS.get('doc')||L[0].slug;
 const show=async()=>{b.innerHTML=`<div style="display:grid;grid-template-columns:240px 1fr;gap:16px;align-items:start"><div class="card snav" style="padding:6px">${L.map(p=>`<a data-d="${p.slug}" class="${p.slug===cur?'on':''}">${ICN('file-text')}${esc(p.title)}</a>`).join('')}</div><div class="card" id="dc" data-noi18n style="max-width:900px;line-height:1.6"></div></div>`;
  b.querySelectorAll('[data-d]').forEach(x=>x.onclick=()=>{cur=x.dataset.d;show()});const r=await fetch('api/server-docs/'+cur+'?format=html',{credentials:'same-origin'});$('dc').innerHTML=await r.text();
  $('dc').querySelectorAll('pre').forEach(p=>p.style.overflow='auto');$('dc').querySelectorAll('table').forEach(t=>{t.style.width='100%'})};show()}
draw();
""")

GW_POL = P("gateway", "LLM Gateway policies", """<div class="ph" id="h"></div><div class="bodyx" id="b"></div>""", r"""
let TAB=QS.get('tab')||'policies',KEYS=[];
const lines=t=>t.split('\n').map(x=>x.trim()).filter(Boolean);
async function draw(){KEYS=await api('api/gw/keys').catch(()=>[]);
 $('h').innerHTML=`<div class="muted" style="font-size:12px;margin-bottom:6px"><a href="gateway">LLM Gateway</a> / Policies &amp; routing</div>`+hdr('route','Policies &amp; routing','<span class="beta">Beta</span>')+tabsHtml([['policies','Per-customer policies'],['routing','Model routing'],['decisions','Decision models']],TAB);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{TAB=b.dataset.tab;history.replaceState(null,'','?tab='+TAB);draw()});
 const b=$('b');b.innerHTML=`<div class="muted">${ICN('loader')} Loading…</div>`;try{await({policies:tPol,routing:tRoute,decisions:tDec}[TAB])(b)}catch(e){b.innerHTML=`<div class="card"><div class="muted">${esc(e.message)}</div></div>`}}
const kname=id=>{const k=KEYS.find(x=>x.id===id);return k?esc(k.name):'all keys'};
async function tPol(b){const P=await api('api/gw/policies');
 b.innerHTML=`<div class="card"><div class="muted" style="font-size:13px;line-height:1.6">Your backend authenticates its end customer and sends <code>X-Gateway-Customer-Id: acme</code> with the gateway key. A policy can <b>separate its default limit by that header</b> (every customer gets the same limit, independently; requests without the header share a fallback bucket) or match <b>one exact value</b>. Names are normalised (<code>Customer-Id</code> = <code>customer_id</code>); identity headers are ignored. Every matching policy is enforced.</div></div>
 <div class="card" style="padding:0"><table><thead><tr><th>Name</th><th>Kind</th><th>Applies to</th><th>Header rule</th><th>Limit</th><th>On</th><th></th></tr></thead><tbody>${P.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td><span class="chip">${p.kind==='spend'?'Spend / month':'Rate / minute'}</span></td><td>${p.vkey_id?kname(p.vkey_id):'every key'} · ${p.scope==='key'?'per key':'whole workspace'}</td><td class="mono" style="font-size:12.5px">${p.match_header?esc(p.match_header)+' = '+esc(p.match_value):(p.header?'separate by '+esc(p.header):'—')}</td><td>${p.kind==='spend'?'$'+p.limit_usd_month:p.rpm+' req/min'}</td><td>${sw('on'+p.id,p.enabled)}</td><td><button class="gh" data-d="${p.id}">${ICN('trash-2')}</button></td></tr>`).join('')||`<tr><td colspan="7" class="muted">No policies yet.</td></tr>`}</tbody></table></div>
 <div class="grid2" style="align-items:start"><div class="card"><div class="h4">New policy</div><label>Name</label><input id="pn" style="width:100%" placeholder="Per-customer cap">
  <div class="row" style="margin-top:6px"><select id="pk"><option value="spend">Spend (USD / month)</option><option value="rate">Rate (requests / minute)</option></select><select id="ps"><option value="key">per key</option><option value="workspace">whole workspace</option></select><select id="pv"><option value="">every key</option>${KEYS.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select></div>
  <label>Header rule</label><div class="row"><select id="pm"><option value="none">None (plain limit)</option><option value="sep">Separate by header</option><option value="exp">Explicit condition</option></select><input id="ph" placeholder="Header, e.g. Customer-Id" style="width:180px"><input id="pval" placeholder="value (explicit only)" style="width:150px"></div>
  <label>Limit</label><input id="pl" type="number" step="any" value="10" style="width:120px"><div class="row" style="margin-top:10px"><button id="pgo">${ICN('plus')}Create policy</button></div></div>
  <div class="card"><div class="h4">Lock a key to a customer</div><div class="muted" style="font-size:12.5px;margin:2px 0 8px">A client that holds the key can choose its own header, and so its own bucket. Fix it per key: <b>allow</b> (which headers clients may set), <b>strip</b>, <b>inject</b> (values you fix; the client cannot override).</div>
  <select id="hk" style="width:100%">${KEYS.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select><label>Allow <small class="muted">(one per line; empty = any)</small></label><textarea id="ha" rows="2" class="mono"></textarea><label>Strip</label><textarea id="hs" rows="2" class="mono"></textarea><label>Inject <small class="muted">(name=value)</small></label><textarea id="hi" rows="2" class="mono" placeholder="customer_id=acme"></textarea><div class="row" style="margin-top:8px"><button class="g" id="hgo">Save header policy</button></div></div></div>`;
 P.forEach(p=>{const c=document.getElementById('on'+p.id);if(c)c.onchange=async()=>{await api('api/gw/policies/'+p.id,'PATCH',{enabled:c.checked});flash(c.checked?'Enabled':'Disabled')}});
 b.querySelectorAll('[data-d]').forEach(x=>x.onclick=async()=>{if(confirm('Delete this policy?')){await api('api/gw/policies/'+x.dataset.d,'DELETE');tPol(b)}});
 $('pgo').onclick=async()=>{const k=$('pk').value,m=$('pm').value,body={name:$('pn').value||'policy',kind:k,scope:$('ps').value,vkey_id:$('pv').value?+$('pv').value:null};if(k==='spend')body.limit_usd_month=+$('pl').value;else body.rpm=Math.round(+$('pl').value);
  if(m==='sep')body.header=$('ph').value;if(m==='exp'){body.match_header=$('ph').value;body.match_value=$('pval').value}try{await api('api/gw/policies','POST',body);flash('Policy created');tPol(b)}catch(e){flash(e.message,1)}};
 const loadHp=async()=>{if(!$('hk').value)return;const r=await api('api/gw/keys/'+$('hk').value+'/routing');const h=r.header_policy||{};$('ha').value=(h.allow||[]).join('\n');$('hs').value=(h.strip||[]).join('\n');$('hi').value=Object.entries(h.inject||{}).map(([k,v])=>k+'='+v).join('\n')};$('hk').onchange=loadHp;loadHp();
 $('hgo').onclick=async()=>{const inj={};lines($('hi').value).forEach(l=>{const i=l.indexOf('=');if(i>0)inj[l.slice(0,i).trim()]=l.slice(i+1).trim()});try{await api('api/gw/keys/'+$('hk').value+'/header-policy','PUT',{allow:lines($('ha').value),strip:lines($('hs').value),inject:inj});flash('Saved')}catch(e){flash(e.message,1)}}}
const RULES_EX={mode:'rules',objective:'balanced',tiers:[{name:'fast',model:'gemini-flash-lite-latest'},{name:'balanced',model:'gemini-3.6-flash'},{name:'strong',model:'gemini-3.8-flash'}],default_tier:'balanced',rules:[{if:{max_chars:300},tier:'fast'},{if:{contains:['prove','analyse','refactor']},tier:'strong'}]};
async function tRoute(b){if(!KEYS.length){b.innerHTML=`<div class="card">${emptyState('key-round','No virtual keys','Create a virtual key first; routing is a policy of a key.','<a class="btn" href="classic/gwkeys">Virtual keys</a>')}</div>`;return}
 b.innerHTML=`<div class="card"><div class="muted" style="font-size:13px;line-height:1.6">Clients ask for <code>model: "auto"</code>; the key's routing policy picks the model. <b>rules</b>: size / tools / images / keywords. <b>decision</b>: a small model rates the request first (<code>complexity</code>, <code>needs_reasoning</code>). The <b>objective</b> moves the choice one tier down (cost) or up (quality); <b>max latency</b> avoids tiers this gateway measured as too slow.</div></div>
 <div class="grid2" style="align-items:start"><div class="card"><div class="row"><select id="rk">${KEYS.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select><span class="sp"></span><button class="g sm" id="rex">Rules example</button><button class="g sm" id="dex">Decision example</button></div><textarea id="rj" rows="18" class="mono" style="width:100%;margin-top:8px" placeholder="No routing policy on this key"></textarea><div class="row" style="margin-top:8px"><button id="rs">Save routing</button><button class="g" id="rd">Remove</button></div></div>
 <div class="card"><div class="h4">Test</div><label>User message</label><textarea id="rm" rows="4" style="width:100%">Please prove that the sum of two even numbers is even.</textarea><div class="row" style="margin-top:8px"><button class="g" id="rt">${ICN('route')}Which model?</button></div><div id="ro" style="margin-top:10px"></div></div></div>`;
 const load=async()=>{const r=await api('api/gw/keys/'+$('rk').value+'/routing');$('rj').value=r.routing?JSON.stringify(r.routing,null,1):''};$('rk').onchange=load;load();
 $('rex').onclick=()=>$('rj').value=JSON.stringify(RULES_EX,null,1);$('dex').onclick=()=>$('rj').value=JSON.stringify({...RULES_EX,mode:'decision',objective:'cost',decision_model:'gemini-flash-lite-latest',rules:[],max_latency_ms:4000},null,1);
 $('rs').onclick=async()=>{try{await api('api/gw/keys/'+$('rk').value+'/routing','PUT',JSON.parse($('rj').value));flash('Saved')}catch(e){flash(e.message,1)}};
 $('rd').onclick=async()=>{await api('api/gw/keys/'+$('rk').value+'/routing','DELETE');flash('Removed');load()};
 $('rt').onclick=async()=>{try{const body={messages:[{role:'user',content:$('rm').value}]};try{body.routing=JSON.parse($('rj').value)}catch(e){body.key_id=+$('rk').value}const r=await api('api/gw/route/test','POST',body);
  $('ro').innerHTML=`<div class="card" style="border-color:var(--brand)"><div class="row"><span class="chip ok" style="font-size:14px">${esc(r.model)}</span><span class="chip">${esc(r.tier)}</span><span class="chip">${esc(r.mode)}</span></div><div class="muted" style="margin-top:6px">${esc(r.reason)}</div>${r.decision?`<pre style="margin-top:6px">${esc(JSON.stringify(r.decision,null,1))}</pre><small class="muted">decided by ${esc(r.decision_model)}</small>`:''}</div>`}catch(e){flash(e.message,1)}}}
async function tDec(b){const O=location.origin;
 b.innerHTML=`<div class="card"><div class="h4">POST /v1/decisions</div><div class="muted" style="font-size:13px;line-height:1.6;margin:2px 0 8px">Classify or score text with named questions; the answer is structured data, not a chat message. Question types: <code>predicate</code> (probability), <code>choice</code> (one of the options), <code>score</code> (a number in a scale). Runs on a small model under the key's budget, rate limits, PII mode and per-customer policies.</div>
 <pre style="user-select:all;white-space:pre-wrap">curl ${esc(O)}/v1/decisions \
  -H "Authorization: Bearer vk-…" -H "Content-Type: application/json" \
  -d '{"input": "The package arrived with a broken screen.",
       "questions": [
        {"type": "predicate", "name": "damaged", "instructions": "Does the customer report a damaged item?"},
        {"type": "choice", "name": "topic", "instructions": "Main topic", "options": ["shipping", "product", "billing"]},
        {"type": "score", "name": "anger", "instructions": "How angry is the customer?", "scale": [0, 10]}]}'</pre>
 <pre>{"model": "gemini-flash-lite-latest", "answers": [
  {"type": "predicate", "name": "damaged", "probability": 0.97},
  {"type": "choice", "name": "topic", "choice": "shipping"},
  {"type": "score", "name": "anger", "score": 6}], "usage": {"input_tokens": 164, "output_tokens": 38, "total_tokens": 202}}</pre>
 <div class="muted" style="font-size:12.5px">An answer that is out of range is clamped; one that is not valid comes back as <code>"error": "no valid answer"</code> — nothing is guessed. The routing tab can use the same kind of model to choose the model for a request.</div></div>`}
draw();
""")

PAGES = {"/apps": APPS, "/server-config": SERVER_CFG, "/gateway-policies": GW_POL}
